ru.v13.ms.console.example:
# Консоль ModScript: пишите команды — справа сразу вывод,
# переменные и что получится в моде.
let price = 40
repeat 3 {
  inc price 5
}
print "Цена: $price"

option Difficulty = normal easy normal hard
recipe "Ягодный пирог" = "296 1 246 1/1 10/0/default"
edit "Data/Objects" "472" Price = $price

switch $Difficulty {
  case easy {
    print "легко"
  }
  default {
    print "как задумано"
  }
}
debug price

en.v13.ms.console.example:
# ModScript console: type commands and see the output,
# variables and what the mod will contain on the right.
let price = 40
repeat 3 {
  inc price 5
}
print "Price: $price"

option Difficulty = normal easy normal hard
recipe "Berry Pie" = "296 1 246 1/1 10/0/default"
edit "Data/Objects" "472" Price = $price

switch $Difficulty {
  case easy {
    print "easy"
  }
  default {
    print "as intended"
  }
}
debug price
